import{_ as e,c as a,a1 as n,o}from"./chunks/framework.CnnR69hl.js";const m=JSON.parse('{"title":"Core Components Overview","description":"","frontmatter":{"title":"Core Components Overview"},"headers":[],"relativePath":"langchain/langchain-components.md","filePath":"langchain/langchain-components.md"}'),r={name:"langchain/langchain-components.md"};function s(l,t,i,p,c,d){return o(),a("div",null,[...t[0]||(t[0]=[n(`<p>LangChain মূলত ৬টি core component নিয়ে গঠিত। প্রতিটা component কী কাজ করে এবং একটা আরেকটার সাথে কীভাবে যুক্ত — এটা বুঝলে বাকি পুরো ডকুমেন্টেশন (Prompt Templates, Chains, Memory, Agents ইত্যাদি) পড়া অনেক সহজ হয়ে যাবে, কারণ এরপরের প্রতিটা topic আসলে এই ৬টার একটার detail explanation।</p><p>এই পেজটা একদম <strong>conceptual overview</strong> — কোনো কোড নেই এখানে। প্রতিটা component নিয়ে আলাদা, বিস্তারিত পেজ পরে আসবে working code সহ।</p><h2 id="বড়-ছবি-big-picture" tabindex="-1">বড় ছবি (Big Picture) <a class="header-anchor" href="#বড়-ছবি-big-picture" aria-label="Permalink to &quot;বড় ছবি (Big Picture)&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Models      → AI-এর মূল মস্তিষ্ক (LLM এবং embedding model)</span></span>
<span class="line"><span>Prompts     → model কে কী পাঠাচ্ছো</span></span>
<span class="line"><span>Chains      → একাধিক ধাপ কীভাবে একসাথে যুক্ত হচ্ছে</span></span>
<span class="line"><span>Indexes     → model কীভাবে তোমার নিজের ডেটা access করবে</span></span>
<span class="line"><span>Memory      → আগের কথোপকথন কীভাবে মনে রাখবে</span></span>
<span class="line"><span>Agents      → model কীভাবে সিদ্ধান্ত নেয় কী action নিতে হবে</span></span></code></pre></div><p>প্রতিটা LangChain application আসলে এই ৬টা জিনিসের কোনো না কোনো combination।</p><hr><h2 id="১-models" tabindex="-1">১. Models <a class="header-anchor" href="#১-models" aria-label="Permalink to &quot;১. Models&quot;">​</a></h2><p>Models হলো তোমার code আর actual AI provider (OpenAI, Anthropic, Google ইত্যাদি) এর মাঝের interface layer। LangChain এই interface-টা standardize করে দেয়, ফলে provider বদলালে পুরো application নতুন করে লিখতে হয় না।</p><p>এখানে দুই ধরনের model আছে:</p><table tabindex="0"><thead><tr><th>ধরন</th><th>Input → Output</th><th>কোথায় ব্যবহার হয়</th></tr></thead><tbody><tr><td><strong>Language Models</strong></td><td>Text ইনপুট → Text আউটপুট</td><td>Chat, summarization, text generation</td></tr><tr><td><strong>Embedding Models</strong></td><td>Text ইনপুট → Vector আউটপুট</td><td>Semantic search, RAG retrieval</td></tr></tbody></table><p>যেহেতু দুই ধরনের model-ই একই standard interface follow করে, <code>ChatOpenAI</code> দিয়ে লেখা code আর <code>ChatAnthropic</code> দিয়ে লেখা code প্রায় একই রকম দেখতে — শুধু import আর constructor বদলায়।</p><blockquote><p>বিস্তারিত পাবে <a href="/NextGen-AI/langchain/chat-models.html">Chat Models</a> এবং <a href="/NextGen-AI/langchain/embeddings.html">Embeddings</a> পেজে।</p></blockquote><hr><h2 id="২-prompts" tabindex="-1">২. Prompts <a class="header-anchor" href="#২-prompts" aria-label="Permalink to &quot;২. Prompts&quot;">​</a></h2><p>LLM এর output কেমন হবে সেটা অনেকখানি নির্ভর করে input কীভাবে লেখা হচ্ছে তার উপর। Prompts component তোমাকে সেই input reliably বানানোর টুলস দেয় — যেন প্রতিবার raw string hardcode করতে না হয়।</p><p>মূল সুবিধাগুলো:</p><ul><li><strong>Dynamic template</strong> — একটা reusable prompt structure এ variable বসানো</li><li><strong>Role-based prompt</strong> — system instruction আর user input আলাদা রাখা (chat model এর জন্য গুরুত্বপূর্ণ)</li><li><strong>Few-shot prompting</strong> — আসল প্রশ্ন করার আগে model কে কিছু example দেখিয়ে দেওয়া, যাতে সে pattern বুঝে নেয়</li></ul><blockquote><p>বিস্তারিত পাবে <a href="/NextGen-AI/langchain/prompt-templates.html">Prompt Templates</a> পেজে।</p></blockquote><hr><h2 id="৩-chains" tabindex="-1">৩. Chains <a class="header-anchor" href="#৩-chains" aria-label="Permalink to &quot;৩. Chains&quot;">​</a></h2><p>Chains হলো এই framework-এর নামের উৎস — এটা একাধিক component কে এমনভাবে যুক্ত করে যে এক ধাপের output পরের ধাপের input হয়ে যায়। এটাই আলাদা আলাদা building block কে একটা কার্যকর pipeline এ পরিণত করে।</p><p>Chain তিনভাবে চলতে পারে:</p><ul><li><strong>Sequentially</strong> — একটার পর একটা ধাপ</li><li><strong>Parallel এ</strong> — একসাথে একাধিক independent ধাপ চলে, শেষে merge হয়</li><li><strong>Conditionally</strong> — input অনুযায়ী আলাদা path বেছে নেয়</li></ul><blockquote><p>বিস্তারিত পাবে <a href="/NextGen-AI/langchain/langchain-expression-language.html">LCEL</a> এবং <a href="/NextGen-AI/langchain/chains.html">Chains</a> পেজে।</p></blockquote><hr><h2 id="৪-indexes" tabindex="-1">৪. Indexes <a class="header-anchor" href="#৪-indexes" aria-label="Permalink to &quot;৪. Indexes&quot;">​</a></h2><p>Indexes তোমার application কে বাইরের ডেটার সাথে যুক্ত করে — PDF, website, internal database — যেকোনো কিছু যা model আগে থেকে জানে না। এটাই RAG (Retrieval-Augmented Generation) এর মূল ভিত্তি।</p><p>Indexes আসলে চারটা sub-tool একসাথে কাজ করে:</p><table tabindex="0"><thead><tr><th>Sub-component</th><th>কাজ</th></tr></thead><tbody><tr><td><strong>Document Loaders</strong></td><td>PDF, website, database থেকে raw content নিয়ে আসা</td></tr><tr><td><strong>Text Splitters</strong></td><td>বড় document কে ছোট ছোট chunk এ ভাগ করা</td></tr><tr><td><strong>Vector Stores</strong></td><td>chunk গুলোকে embedding হিসেবে সংরক্ষণ করা যাতে দ্রুত semantic search করা যায়</td></tr><tr><td><strong>Retrievers</strong></td><td>নির্দিষ্ট query এর জন্য সবচেয়ে relevant chunk খুঁজে বের করা</td></tr></tbody></table><blockquote><p>বিস্তারিত পাবে <a href="/NextGen-AI/langchain/vector-stores.html">Vector Stores</a>, <a href="/NextGen-AI/langchain/retrievers.html">Retrievers</a>, এবং <a href="/NextGen-AI/langchain/rag.html">RAG</a> পেজে।</p></blockquote><hr><h2 id="৫-memory" tabindex="-1">৫. Memory <a class="header-anchor" href="#৫-memory" aria-label="Permalink to &quot;৫. Memory&quot;">​</a></h2><p>LLM API call by default stateless — প্রতিটা call independent, এবং তুমি আগের history নিজে থেকে পাঠিয়ে না দিলে model আগের কথা কিছুই মনে রাখবে না। Memory component এটাই manage করে।</p><p>সাধারণ পদ্ধতি:</p><ul><li><strong>Conversation Buffer Memory</strong> — পুরো conversation history সংরক্ষণ করে প্রতি call এ পাঠানো</li><li><strong>Summarization Memory</strong> — conversation বড় হয়ে গেলে পুরোনো অংশ সংক্ষেপ (summary) করে context জায়গা বাঁচানো</li></ul><blockquote><p>বিস্তারিত পাবে <a href="/NextGen-AI/langchain/memory.html">Memory</a> পেজে।</p></blockquote><hr><h2 id="৬-agents" tabindex="-1">৬. Agents <a class="header-anchor" href="#৬-agents" aria-label="Permalink to &quot;৬. Agents&quot;">​</a></h2><p>Agents সবচেয়ে advanced component — এটা model এর reasoning ক্ষমতাকে বাইরের tool (search, calculator, API, custom function) এর সাথে যুক্ত করে। শুধু text generate করার বদলে, agent নিজে সিদ্ধান্ত নেয় কাজটা সম্পন্ন করতে <strong>কী কী action</strong> নিতে হবে — প্রয়োজনে একাধিক ধাপে।</p><p>এটাই সেই পরিবর্তন — &quot;শুধু প্রশ্নের উত্তর দেওয়া chatbot&quot; থেকে &quot;নিজে থেকে কাজ করতে পারা system&quot; এ যাওয়া।</p><blockquote><p>বিস্তারিত পাবে <a href="/NextGen-AI/langchain/tools.html">Tools</a>, <a href="/NextGen-AI/langchain/tool-calling.html">Tool Calling</a>, এবং <a href="/NextGen-AI/langchain/agents.html">Agents</a> পেজে।</p></blockquote><hr><h2 id="বাস্তব-app-এ-এই-৬টা-কীভাবে-একসাথে-কাজ-করে" tabindex="-1">বাস্তব App এ এই ৬টা কীভাবে একসাথে কাজ করে <a class="header-anchor" href="#বাস্তব-app-এ-এই-৬টা-কীভাবে-একসাথে-কাজ-করে" aria-label="Permalink to &quot;বাস্তব App এ এই ৬টা কীভাবে একসাথে কাজ করে&quot;">​</a></h2><p>একটা সাধারণ RAG-ভিত্তিক chatbot প্রায় সবগুলো component ব্যবহার করে:</p><ol><li><strong>Indexes</strong> থেকে relevant তথ্যের chunk খুঁজে বের করা হয়</li><li><strong>Prompts</strong> সেই chunk গুলো আর user এর প্রশ্ন একসাথে format করে</li><li><strong>Models</strong> response generate করে</li><li><strong>Chains</strong> ১-৩ নম্বর ধাপগুলো একসাথে জোড়ে</li><li><strong>Memory</strong> conversation টা চলমান রাখে</li><li><strong>Agents</strong> (যদি দরকার হয়) সিদ্ধান্ত নেয় উত্তর দেওয়ার আগে কোনো tool call লাগবে কিনা</li></ol><p>এই ৬টা component মাথায় রেখে বাকি ডকুমেন্টেশন পড়লে প্রতিটা নতুন topic কেন আছে এবং পুরো ছবির কোথায় fit করছে — সেটা বুঝতে অনেক সহজ হবে।</p><h2 id="পরবর্তী-ধাপ" tabindex="-1">পরবর্তী ধাপ <a class="header-anchor" href="#পরবর্তী-ধাপ" aria-label="Permalink to &quot;পরবর্তী ধাপ&quot;">​</a></h2><p>এরপর যাও <a href="/NextGen-AI/langchain/installation.html">Installation</a> পেজে environment সেটআপ করতে, তারপর sidebar এর order অনুযায়ী একটা একটা করে component শেখা শুরু করো।</p>`,48)])])}const g=e(r,[["render",s]]);export{m as __pageData,g as default};
